import itertools
T={'t':t,'1':np.ones_like(t),'sin':np.sin(t),'cos':np.cos(t),'exp-t':np.exp(-t),'sqrt':np.sqrt(t),'1/t':1/t,'t2':t**2,'logt':np.log(t),'exp-t/2':np.exp(-t/2),'sin2':np.sin(2*t),'cos2':np.cos(2*t),'t*exp-t':t*np.exp(-t)}
Pf={'P':P,'1':np.ones_like(P),'P2':P**2,'P3':P**3,'sqrtP':np.sqrt(P),'1/P':1/P,'expP':np.exp(-P),'P/(1+P)':P/(1+P),'log1P':np.log(1+P),'PexpP':P*np.exp(-P),'sinP':np.sin(P),'cosP':np.cos(P),'PlogP':P*np.log(P),'P2expP':P**2*np.exp(-P)}
cands={}
for a_,x in T.items():
    for b_,z in Pf.items():
        cands[a_+'*'+b_]=x*z
keys=list(cands.keys())
y=dP_dt
best=[]
for c3 in [0.3,0.7,1.0,1.5,2.5,4,8]:
    L=np.log(1+c3*P)*t
    base=np.column_stack([P**2,L])
    for k1,k2 in itertools.combinations(keys,2):
        B=np.column_stack([base,cands[k1],cands[k2]])
        b=np.linalg.lstsq(B,y,rcond=None)[0]
        e=np.mean((B@b-y)**2)/np.var(y)
        best.append((round(e,7),c3,k1,k2,np.round(b,4)))
best.sort(key=lambda z:z[0])
for z in best[:6]: print(z)
